analyticsRoutes.get("/stats", async (c2) => {
  const since = Number(c2.req.query("since") || 0);
  const limit = Math.min(Number(c2.req.query("limit") || 5e3), 2e4);
  let store4;
  try {
    store4 = (0, import_pages_blob2.getStore)(STORE2);
  } catch (e2) {
    return c2.json({ error: "store_unavailable", message: String(e2.message || e2) }, 500);
  }
  let keys = [];
  try {
    const listed = await store4.list({ prefix: "events/" });
    const arr = listed.blobs || [];
    keys = arr.map((b2) => b2.key).filter(Boolean);
  } catch (e2) {
    return c2.json({ error: "list_failed", message: String(e2.message || e2) }, 500);
  }
  const utm = {}, entry = {};
  const subject = {}, flow = {}, hourly = {};
  let total = 0;
  const recent = keys.slice(-limit);
  for (const key of recent) {
    let ev;
    try {
      ev = await store4.get(key, { type: "json" });
    } catch {
      continue;
    }
    if (!ev) continue;
    const ts = Number(ev.serverTs || ev.ts || 0);
    if (since && ts < since) continue;
    total++;
    if (ev.utm_source) utm[String(ev.utm_source)] = (utm[String(ev.utm_source)] || 0) + 1;
    if (ev.entry) entry[String(ev.entry)] = (entry[String(ev.entry)] || 0) + 1;
    if (ev.subjectId) subject[String(ev.subjectId)] = (subject[String(ev.subjectId)] || 0) + 1;
    if (ev.fromPage && ev.toPage) {
      const f2 = `${ev.fromPage}\u2192${ev.toPage}`;
      flow[f2] = (flow[f2] || 0) + 1;
    }
    if (ts) {
      const hour = new Date(ts).toISOString().slice(0, 13);
      hourly[hour] = (hourly[hour] || 0) + 1;
    }
  }
  c2.res.headers.set("Access-Control-Allow-Origin", "*");
  c2.res.headers.set("Cache-Control", "no-store");
  return c2.json({
    ok: true,
    total,
    availableKeys: keys.length,
    byUtmSource: topN(utm),
    byEntry: topN(entry),
    bySubject: topN(subject),
    byFlow: topN(flow),
    byHour: Object.entries(hourly).sort((a2, b2) => a2[0].localeCompare(b2[0])).map(([key, count]) => ({ key, count }))
  });
});
async function rankHandler(c2, fixed) {
  const raw3 = (fixed || c2.req.query("type") || "total").toLowerCase();
  const type = ["today", "week", "month"].includes(raw3) ? raw3 : "total";
  const limit = Math.min(Math.max(Number(c2.req.query("limit") || 20) || 20, 1), 100);
  c2.res.headers.set("Access-Control-Allow-Origin", "*");
  c2.res.headers.set("Cache-Control", "public, max-age=60");
  return c2.json(await rankByType(type, limit));
}
analyticsRoutes.get("/stats/rank", (c2) => rankHandler(c2));
analyticsRoutes.get("/stats/rank/top", (c2) => rankHandler(c2));
analyticsRoutes.get("/stats/rank/today", (c2) => rankHandler(c2, "today"));
analyticsRoutes.get("/stats/rank/day", (c2) => rankHandler(c2, "today"));
analyticsRoutes.get("/stats/rank/week", (c2) => rankHandler(c2, "week"));
analyticsRoutes.get("/stats/rank/month", (c2) => rankHandler(c2, "month"));
analyticsRoutes.get("/stats/rank/total", (c2) => rankHandler(c2, "total"));

